ucs.falcon_logscale_query:
(#event_simpleName=ProcessRollup2 OR #event_simpleName=DriverLoad)
| stage := case {
    ImageFileName=/\\vssadmin\.exe$/i AND regex("(?i)delete\\s+shadows", field=CommandLine) | "shadow_delete";
    ImageFileName=/\\wmic\.exe$/i AND regex("(?i)shadowcopy\\s+delete", field=CommandLine) | "shadow_delete";
    ImageFileName=/\\rundll32\.exe$/i AND regex("(?i)comsvcs\\.dll.*MiniDump", field=CommandLine) | "lsass_dump";
    ImageFileName=/\\procdump(64)?\.exe$/i AND regex("(?i)lsass", field=CommandLine) | "lsass_dump";
    regex("(?i)\\\\(zemana|rwdrv|gmer|truesight|aswarpot|kprocesshacker|partyrocking)\\.sys", field=CommandLine) | "byovd_load";
    ImageFileName=/\\(taskkill|net|sc)\.exe$/i AND regex("(?i)(WinDefend|Sense|MsMpSvc|SentinelAgent|CSFalcon|CylanceSvc|SophosAgent|Veeam)", field=CommandLine) | "edr_or_backup_kill";
    regex("(?i)Veeam.*(Credential|Backup\\.Common|xml)", field=CommandLine) | "veeam_cred_dump";
    * | "other";
  }
| stage != "other"
| bucket(span=1h, field=@timestamp)
| groupBy([aid, ComputerName, _bucket], function=[count(field=stage, distinct=true, as=DistinctStages), collect([stage, CommandLine], multival=true)])
| DistinctStages >= 3
